def build_agent(sandbox):
    # Create a horizontal beam at y=2.5 from x=6 to x=18 (width 12 m, height 0.1 m)
    beam = sandbox.add_beam(x=6 + 12/2, y=2.5, width=12, height=0.1, angle=0, density=250.0)
    # Anchor the beam to the ground at its bottom edge (y=2.5 - 0.05)
    anchor_point = (6 + 12/2, 2.5 - 0.05)
    joint = sandbox.add_joint(beam, None, anchor_point, type='rigid')
    return beam

def agent_action(sandbox, agent_body, step_count):
    particles = sandbox.get_fluid_particles()
    for particle in particles:
        x, y = particle.position.x, particle.position.y
        fx = 0.0
        fy = 0.0

        # Lift particles to the beam (y=2.5) if they are in the source area (x < 6)
        if x < 6:
            if y < 2.5:
                fy += 100.0  # Upward force to reach beam height
            else:
                # Already at beam height, apply eastward force
                fx += 100.0
        elif 6 <= x <= 18:
            # On the beam, apply eastward force
            fx += 100.0
        else:
            # Past the beam, apply downward force to lower to target
            if y > 1.5:
                fy -= 100.0  # Downward force to reach target height

        # Counteract gravity well in x [10,14], y [1.5,3.5]
        if 10 <= x <= 14 and 1.5 <= y <= 3.5:
            fy += 100.0  # Upward force to counteract downward gravity

        # Apply force to particle
        sandbox.apply_force_to_particle(particle, fx, fy)

